-- Pool model: one table for all tenants, isolated by Postgres row-level security
CREATE TABLE documents (
  id         bigserial PRIMARY KEY,
  tenant_id  uuid NOT NULL,
  title      text NOT NULL,
  body       text
);
CREATE INDEX ON documents (tenant_id);          -- every query filters on it

ALTER TABLE documents ENABLE ROW LEVEL SECURITY;
ALTER TABLE documents FORCE ROW LEVEL SECURITY;  -- applies to the table owner too
CREATE POLICY tenant_isolation ON documents
  USING (tenant_id = current_setting('app.tenant_id')::uuid)
  WITH CHECK (tenant_id = current_setting('app.tenant_id')::uuid);

-- The app sets the tenant at the start of each transaction, from the login token
BEGIN;
SET LOCAL app.tenant_id = '6f1c2a7e-0000-4000-8000-00000000a001';
SELECT id, title FROM documents;   -- returns this tenant's rows only
COMMIT;
