import hashlib, hmac, json
import httpx

# One internal shape, three ticketing APIs. Paths are the documented REST routes;
# auth, required fields and custom fields vary per customer instance.
def to_request(system: str, t: dict) -> tuple[str, dict]:
    if system == "servicenow":   # Table API
        return "/api/now/table/incident", {
            "short_description": t["title"], "description": t["body"],
            "urgency": {"high": "1", "medium": "2", "low": "3"}[t["priority"]]}
    if system == "jira":         # v2 accepts a plain-text description
        return "/rest/api/2/issue", {"fields": {
            "project": {"key": "OPS"}, "issuetype": {"name": "Task"},
            "summary": t["title"], "description": t["body"]}}
    if system == "zendesk":
        return "/api/v2/tickets.json", {"ticket": {
            "subject": t["title"], "comment": {"body": t["body"]},
            "priority": {"high": "high", "medium": "normal", "low": "low"}[t["priority"]]}}
    raise ValueError(system)

def fake_server(request: httpx.Request) -> httpx.Response:   # stands in for the real APIs
    return httpx.Response(201, json={"received": request.url.path, "id": "T-1001"})

client = httpx.Client(base_url="https://tickets.example", transport=httpx.MockTransport(fake_server))
ticket = {"title": "Invoice sync failed for 14 records", "body": "See run 8812.", "priority": "high"}
for system in ["servicenow", "jira", "zendesk"]:
    path, payload = to_request(system, ticket)
    r = client.post(path, json=payload)
    print(system, r.status_code, r.json()["received"])

# Incoming webhooks: check a shared-secret HMAC before trusting the body
SECRET = b"from-your-secret-store"
body = json.dumps({"ticket_id": 1001, "status": "solved"}).encode()
sent_sig = hmac.new(SECRET, body, hashlib.sha256).hexdigest()   # what the sender attaches

def verify(raw: bytes, signature: str) -> bool:
    expected = hmac.new(SECRET, raw, hashlib.sha256).hexdigest()
    return hmac.compare_digest(expected, signature)      # constant-time compare

print("valid:", verify(body, sent_sig), "| tampered:", verify(body + b" ", sent_sig))

# Output:
# servicenow 201 /api/now/table/incident
# jira 201 /rest/api/2/issue
# zendesk 201 /api/v2/tickets.json
# valid: True | tampered: False

import json

def fake_llm(system: str, user: str) -> str:
    """Stands in for a model call so this runs offline. Swap in a real client."""
    u = user.lower()
    if system.startswith("ROUTER"):
        if any(w in u for w in ("invoice", "refund", "charged")):
            return json.dumps({"route": "billing", "confidence": 0.9})
        if any(w in u for w in ("error", "crash", "password")):
            return json.dumps({"route": "tech", "confidence": 0.85})
        return json.dumps({"route": "unknown", "confidence": 0.3})
    if system.startswith("BILLING"):
        return "TOOL lookup_invoice " + "".join(c for c in u if c.isdigit())
    return "Try resetting your password from the login page, then clear the app cache."

INVOICES = {"4471": {"amount": 120.0, "status": "paid twice"}}   # fake billing system

def billing_agent(msg: str, trace: list) -> str:
    step = fake_llm("BILLING: answer billing questions; use lookup_invoice.", msg)
    if step.startswith("TOOL lookup_invoice"):
        inv_id = step.split()[-1]
        trace.append(f"billing -> tool lookup_invoice({inv_id})")
        inv = INVOICES.get(inv_id)
        if inv is None:
            return "I could not find that invoice. A person will follow up."
        return f"Invoice {inv_id} for ${inv['amount']:.2f} is {inv['status']}; refund queued for approval."
    return step

def tech_agent(msg: str, trace: list) -> str:
    trace.append("tech -> answer from runbook")
    return fake_llm("TECH: answer from the support runbook only.", msg)

AGENTS = {"billing": billing_agent, "tech": tech_agent}

def handle(msg: str) -> tuple[str, list]:
    trace = []
    decision = json.loads(fake_llm("ROUTER: pick billing or tech as JSON.", msg))
    trace.append(f"router -> {decision['route']} ({decision['confidence']})")
    if decision["route"] not in AGENTS or decision["confidence"] < 0.6:
        trace.append("handoff -> human queue")
        return "Passing you to a person.", trace
    return AGENTS[decision["route"]](msg, trace), trace

for msg in ["I was charged twice on invoice 4471", "App crash after password reset", "Do you sponsor events?"]:
    answer, trace = handle(msg)
    print(f"> {msg}\n  trace: {' ; '.join(trace)}\n  reply: {answer}")

